import sys

def solve(s):
    n = len(s)
    result = list(s)
    for i in range(n):
        if result[i] == '?':
            result[i] = 'A'
    for i in range(n - 3):
        if result[i] == 'C' or result[i] == '?':
            if result[i + 1] == 'H' or result[i + 1] == '?':
                if result[i + 2] == 'E' or result[i + 2] == '?':
                    if result[i + 3] == 'F' or result[i + 3] == '?':
                        result[i] = 'C'
                        result[i + 1] = 'H'
                        result[i + 2] = 'E'
                        result[i + 3] = 'F'
    return ''.join(result)

input = sys.stdin.read().split()
t = int(input[0])
index = 1
for _ in range(t):
    s = input[index]
    index += 1
    print(solve(s))
